-- Phase 2 review fixes, generated by drizzle-kit:
--
-- runs.next_trigger: the trigger the run's next attempt gets, written by the
-- same update that queues the run (launch, the automatic retry, recovery's
-- requeue, Retry and Retry failed runs). A job that is lost and re-sent later
-- (Resume, Retry failed runs, recovery) reads it, so the attempt's provenance
-- no longer depends on guessing from the last attempt. Nullable and added
-- without a default, so nothing is rewritten; rows queued before it fall back
-- to the old rule (queuedRunTrigger). runs_guard checks only the matrix
-- position, so it needs no change.
--
-- artifacts_skipped_reason_ck gains `over_budget`: a file recorded without
-- content because the attempt's collection budget was used up. A CHECK change
-- fires no row trigger, and existing rows hold only `too_large`.

ALTER TABLE "artifacts" DROP CONSTRAINT "artifacts_skipped_reason_ck";--> statement-breakpoint
ALTER TABLE "runs" ADD COLUMN "next_trigger" text;--> statement-breakpoint
ALTER TABLE "runs" ADD CONSTRAINT "runs_next_trigger_ck" CHECK ("runs"."next_trigger" is null or "runs"."next_trigger" in ('initial', 'auto_retry', 'user_retry', 'recovery', 'retry_failed'));--> statement-breakpoint
ALTER TABLE "artifacts" ADD CONSTRAINT "artifacts_skipped_reason_ck" CHECK ("artifacts"."skipped_reason" is null or "artifacts"."skipped_reason" in ('too_large', 'over_budget'));